code:
```go

func BenchmarkAlertingRuleAtomic(b *testing.B) {
	b.ReportAllocs()
	t := atomic.NewTime(time.Time{})
	done := make(chan struct{})
	go func() {
		for i := 0; i < b.N; i++ {
			t.Load()
		}
		close(done)
	}()
	b.RunParallel(func(pb *testing.PB) {
		for pb.Next() {
			t.Store(time.Now())
		}
	})
	<-done
}

func BenchmarkAlertingRuleMutex(b *testing.B) {
	b.ReportAllocs()
	t := time.Time{}
	mtx := sync.Mutex{}
	done := make(chan struct{})
	go func() {
		for i := 0; i < b.N; i++ {
			mtx.Lock()
			_ = t
			mtx.Unlock()
		}
		close(done)
	}()
	b.RunParallel(func(pb *testing.PB) {
		for pb.Next() {
			mtx.Lock()
			t = time.Now()
			mtx.Unlock()
		}
	})
	<-done
}

```

